/* @lc app=leetcode id=1559 lang=kotlin */
class Solution { fun containsCycle(grid: Array<CharArray>): Boolean = IntArray(grid.size * grid[0].size) { it }.let { parent -> DeepRecursiveFunction<Int, Int> { u -> if (parent[u] == u) u else callRecursive(parent[u]).also { parent[u] = it } }.let { find -> grid.indices.any { r -> grid[0].indices.any { c -> listOf(r + 1 to c, r to c + 1).any { (nr, nc) -> nr in grid.indices && nc in grid[0].indices && grid[r][c] == grid[nr][nc] && find(r * grid[0].size + c).let { u -> find(nr * grid[0].size + nc).let { v -> u == v || parent.set(u, v).run { false } } } } } } } } }